// Calcula periodo: dia anterior (seg→pega sex/sab/dom)
const agora = new Date();
const dow = agora.getDay();

let diasInicio = 1;
if (dow === 1) diasInicio = 3; // segunda pega sexta

const di = new Date(agora);
di.setDate(agora.getDate() - diasInicio);
const df = new Date(agora);
df.setDate(agora.getDate() - 1);

const fmt = (d) => String(d.getDate()).padStart(2,'0') + '/' + String(d.getMonth()+1).padStart(2,'0') + '/' + d.getFullYear();
const fmtPG = (d) => d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');

const beginStr = fmt(di);
const endStr = fmt(df);

return [{  json: {    begin: beginStr + ' 00:00:00',    end: endStr + ' 23:59:00',    dataRef: beginStr === endStr ? beginStr : beginStr + ' a ' + endStr,    dataRefPG: fmtPG(di),    begin_timestamp: fmtPG(di) + ' 00:00:00',    end_timestamp: fmtPG(df) + ' 23:59:59'  }}];

const items = $input.all();
const dataRef = $('02 - Calcular Periodo').first().json.dataRef;

if (items.length === 0 || (items.length === 1 && items[0].json._semEventos) || !items[0].json.placa) {
  return [{ json: { _semEventos: true, dataRef } }];
}

const grouped = {};
for (const item of items) {
  const d = item.json;
  const filial = d.filial_operacional || 'DESCONHECIDA';
  if (!grouped[filial]) grouped[filial] = [];
  grouped[filial].push(d);
}

const results = [];
for (const [filial, evs] of Object.entries(grouped)) {
  const total = evs.length;
  const vels = evs.map(e => parseFloat(e.velocidade_registrada) || 0).filter(v => v > 0);
  const velMax = vels.length > 0 ? Math.max(...vels) : 0;
  const velMedia = vels.length > 0 ? Math.round((vels.reduce((s,v) => s+v, 0) / vels.length) * 100) / 100 : 0;

  const porPlaca = {};
  for (const e of evs) {
    if (!porPlaca[e.placa]) porPlaca[e.placa] = { qtd: 0, velMax: 0, modelo: e.modelo || '', provedor: e.provedor_rastreador || '3STEC' };
    porPlaca[e.placa].qtd++;
    const v = parseFloat(e.velocidade_registrada) || 0;
    if (v > porPlaca[e.placa].velMax) porPlaca[e.placa].velMax = v;
  }

  const tabelaPlacas = Object.entries(porPlaca)
    .sort((a,b) => b[1].qtd - a[1].qtd)
    .slice(0, 15)
    .map(([p, d]) => ({ placa: p, qtd: d.qtd, velMax: d.velMax, modelo: d.modelo, provedor: d.provedor }));

  const topOc = [...evs]
    .sort((a,b) => (parseFloat(b.velocidade_registrada)||0) - (parseFloat(a.velocidade_registrada)||0))
    .slice(0, 10)
    .map(e => ({
      placa: e.placa,
      velocidade: e.velocidade_registrada,
      data: e.data_hora_alerta,
      local: (e.cidade || '') + (e.estado ? '/' + e.estado : ''),
      origem: e.provedor_rastreador || '3STEC'
    }));

  const piorEntry = Object.entries(porPlaca)
    .sort((a,b) => b[1].qtd !== a[1].qtd ? b[1].qtd - a[1].qtd : b[1].velMax - a[1].velMax)[0];

  let resumo = '';
  if (piorEntry) {
    const [piorPlaca, piorDados] = piorEntry;
    const evGrave = evs
      .filter(e => e.placa === piorPlaca)
      .sort((a,b) => (parseFloat(b.velocidade_registrada)||0) - (parseFloat(a.velocidade_registrada)||0))[0];

    const local = evGrave
      ? ((evGrave.endereco ? evGrave.endereco + ', ' : '') + (evGrave.cidade || '') + (evGrave.estado ? '/' + evGrave.estado : '')).trim().replace(/^,\s*/, '')
      : 'local nao registrado';
    const nivel = piorDados.velMax >= 120 ? '🔴 CRITICO' : piorDados.velMax >= 100 ? '🟠 ALTO' : '🟡 MODERADO';
    resumo = nivel + ' — Veiculo <strong>' + piorPlaca + '</strong> (' + piorDados.provedor + ') com <strong>' + piorDados.qtd + ' alerta(s)</strong>. '
  + 'Pico de <strong>' + piorDados.velMax + ' km/h</strong>'
  + (local ? ' em <em>' + local + '</em>' : '')
  + '.';
  } else {
    resumo = '✅ Nenhum veiculo com padrao critico identificado.';
  }

  // E-mails centralizados do Banco de Dados (DW)
  const emailDestinoFinal = evs[0].email_destino_db || 'torredecontrole@gritsch.com.br';
  const ccParts = [];
  if (evs[0].email_cc_db) ccParts.push(evs[0].email_cc_db);
  if (evs[0].cc_regional_db) ccParts.push(evs[0].cc_regional_db);
  if (evs[0].cc_global_db) ccParts.push(evs[0].cc_global_db);
  const emailCCFinal = ccParts.join(';').split(/[;,]+/).map(s => s.trim()).filter(Boolean).filter((v, i, a) => a.indexOf(v) === i).join(',');

  results.push({ json: {
    filial,
    dataRef,
    totalEventos: total,
    velMax,
    velMedia,
    tabelaPlacas,
    topOcorrencias: topOc,
    resumoAnalitico: resumo,
    emailDestino: emailDestinoFinal,
    emailCC: emailCCFinal,
    consolidadoDestinatarios: evs[0].consolidado_destinatarios_db || 'jefferson@gritsch.com.br',
    consolidadoCC: evs[0].consolidado_cc_db || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br'
  }});
}

return results;

// ===========================================================================
// 18 - Gerar HTML Email  (identidade visual Grupo Gritsch, v1.0 de 19/08/2026)
//
// Estrutura e dados IDENTICOS a versao aprovada. Mudou so a camada visual,
// para o design system oficial.
//
// PALETA (secao 5 do documento):
//   AZUL GRITSCH    #213035  titulo, numero em destaque
//   VINHO GRITSCH   #8E2E2F  faixa de secao, cabecalho de tabela, divisoria
//   VERMELHO ALERTA #FA1126  valor fora da meta
//   CRITICO         #5A181C  desvio que exige acao imediata
//   ATENCAO         #E8A33D  faixa intermediaria
//   POSITIVO        #13880D  dentro da meta  (NAO usar em box de KPI)
//   CINZA           #4E4D4D  rotulo e texto secundario
//   CINZA BORDA     #BFBFBF  borda de box e card
//   CINZA REGUA     #E2E2E2  borda interna de tabela
//   CINZA FUNDO     #F2F2F2  fundo
//
// REGRAS DO DOCUMENTO APLICADAS:
//   - rotulo SEMPRE em caixa alta, 14 px, #4E4D4D, nunca colorido (7.2)
//   - rotulo em cima, numero embaixo (6.4)
//   - o verde nunca entra em box de KPI (5.3)
//   - cabecalho de tabela em #8E2E2F com texto branco (9.1)
//   - borda de celula 1,6 px #E2E2E2; borda de card 1,6 px #BFBFBF (9.1)
//   - numero em formato brasileiro, ponto no milhar (6.5)
//   - data em dd/mm/aaaa (6.5)
//   - nenhum componente com sombra (2.4)
//
// ADAPTACOES DELIBERADAS PARA E-MAIL (o design system e para slide 1920x1080):
//   - Roboto Condensed com fallback 'Arial Narrow', Arial: Outlook nao carrega
//     webfont, e sem fallback condensado o layout quebraria a largura
//   - corpos reduzidos proporcionalmente (H1 32->24, CORPO 18->13): 1920 px de
//     slide contra 700 px de e-mail
//   - layout em <table>, nao grid/flex, exigencia de cliente de e-mail
// ===========================================================================

const d = $json;

// Formato brasileiro, secao 6.5
const fmtNum = (n) => String(n ?? 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmtDec = (n) => String(n ?? 0).replace('.', ',');

// --- Paleta oficial -------------------------------------------------------
const AZUL      = '#213035';
const VINHO     = '#8E2E2F';
const ALERTA    = '#FA1126';
const CRITICO   = '#5A181C';
const ATENCAO   = '#E8A33D';
const CINZA     = '#4E4D4D';
const BORDA     = '#BFBFBF';
const REGUA     = '#E2E2E2';
const FUNDO     = '#F2F2F2';
const BRANCO    = '#FFFFFF';

const FONTE = "'Roboto Condensed','Arial Narrow',Arial,sans-serif";

// Duas versoes da marca, porque o fundo muda: a colorida (cinza + vinho) no
// cabecalho branco, a branca no rodape azul. Usar a branca em cima deixaria a
// logo invisivel. Ambas ficam a ESQUERDA, que e o padrao da empresa.
const LOGO_ESCURA = 'https://gritsch.com.br/wp-content/uploads/2022/03/logomarca-1_gritsch-1.png';
const LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';

// Severidade do excesso. Todo evento aqui JA esta acima do limite da classe,
// entao nenhum e "positivo" — a graduacao vai de atencao a critico.
const corVelocidade = (v) => (v >= 140 ? CRITICO : v >= 120 ? ALERTA : ATENCAO);

// Badge de origem. Cores de marca, nao decorativas.
const badgeOrigem = (p) => {
  const prov = p || '3STEC';
  const cor = prov === '3STEC' ? AZUL : prov === 'OMNILINK' ? CINZA : VINHO;
  return '<span style="display:inline-block;padding:3px 8px;font-size:11px;font-weight:700;'
       + 'color:' + BRANCO + ';background:' + cor + ';border-radius:4px;'
       + 'font-family:' + FONTE + '">' + prov + '</span>';
};

// --- Componentes ----------------------------------------------------------
const th = (txt, align) =>
  '<th style="padding:10px 12px;text-align:' + (align || 'left') + ';font-size:12px;'
  + 'font-weight:700;text-transform:uppercase;color:' + BRANCO + ';background:' + VINHO + ';'
  + 'font-family:' + FONTE + '">' + txt + '</th>';

const td = (conteudo, align, cor, peso) =>
  '<td style="padding:10px 12px;border-bottom:1.6px solid ' + REGUA + ';font-size:13px;'
  + 'text-align:' + (align || 'left') + ';color:' + (cor || CINZA) + ';'
  + 'font-weight:' + (peso || '400') + ';font-family:' + FONTE + '">' + conteudo + '</td>';

// Box de KPI, secao 7: rotulo em caixa alta em cima, numero embaixo
const boxKpi = (rotulo, valor, unidade, corNumero) =>
  '<td width="33%" valign="top" style="padding:0 8px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + BRANCO + ';'
  + 'border:1.6px solid ' + BORDA + ';border-radius:12px"><tr><td style="padding:14px 20px">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
  + 'font-family:' + FONTE + '">' + rotulo + '</div>'
  + '<div style="font-size:26px;font-weight:700;color:' + (corNumero || AZUL) + ';margin-top:4px;'
  + 'font-family:' + FONTE + '">' + valor
  + (unidade ? '<span style="font-size:13px;font-weight:400;color:' + CINZA + '"> ' + unidade + '</span>' : '')
  + '</div></td></tr></table></td>';

// Faixa de secao, secao 7.5: 38 px, vinho, raio 10 px so no topo
const faixaSecao = (titulo) =>
  '<tr><td style="padding:26px 32px 0">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + VINHO + ';border-radius:10px 10px 0 0;padding:9px 20px;'
  + 'font-size:14px;font-weight:700;color:' + BRANCO + ';font-family:' + FONTE + '">'
  + titulo + '</td></tr></table></td></tr>';

// --- Caixa de resumo ------------------------------------------------------
// O node 14 monta o texto ja com <strong>/<em> e um emoji de nivel na frente.
// O emoji sai: o nivel passa a ser cor + rotulo, que e como o design system
// trata severidade (secao 5.3). O texto em si e preservado como veio.
const resumoTxt = String(d.resumoAnalitico || '');
const ehOk = /^\s*(✅|&#9989;)/.test(resumoTxt);
const nivel = ehOk        ? 'Sem padrão crítico'
            : /CRITICO/i.test(resumoTxt) ? 'Crítico'
            : /ALTO/i.test(resumoTxt)    ? 'Alto'
            : 'Moderado';
const corNivel = ehOk        ? POSITIVO
               : /CRITICO/i.test(resumoTxt) ? ALERTA
               : ATENCAO;
const corpoResumo = resumoTxt
  .replace(/^[\s✀-➿\uD83C-􏰀-\uDFFF☀-⛿️]+/u, '')
  .replace(/^(CRITICO|ALTO|MODERADO)\s*[—-]\s*/i, '')
  .trim();

const boxResumo = corpoResumo
  ? '<tr><td style="padding:22px 32px 0">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + corNivel + ';border-radius:0 8px 8px 0">'
    + '<tr><td style="padding:16px 22px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
    + 'font-family:' + FONTE + '">Leitura do período · ' + nivel + '</div>'
    + '<div style="font-size:14px;color:' + CINZA + ';margin-top:7px;line-height:1.7;'
    + 'font-family:' + FONTE + '">' + corpoResumo + '</div>'
    + '</td></tr></table></td></tr>'
  : '';

// --- Linhas das tabelas ---------------------------------------------------
let rowsTop = '';
for (const o of (d.topOcorrencias || [])) {
  const v = o.velocidade || 0;
  const modelo = (d.tabelaPlacas || []).find(x => x.placa === o.placa)?.modelo || '—';
  rowsTop += '<tr>'
    + td(o.placa, 'left', AZUL, '700')
    + td(modelo, 'left')
    + td(badgeOrigem(o.origem), 'center')
    + td(fmtDec(v) + ' km/h', 'right', corVelocidade(v), '700')
    + td(o.data || '—', 'left')
    + td(o.local || o.cidade || '—', 'left')
    + '</tr>';
}

let rowsPlacas = '';
for (const p of (d.tabelaPlacas || [])) {
  const v = p.velMax || 0;
  rowsPlacas += '<tr>'
    + td(p.placa, 'left', AZUL, '700')
    + td(p.modelo || '—', 'left')
    + td(badgeOrigem(p.provedor), 'center')
    + td(fmtNum(p.qtd), 'center')
    + td(fmtDec(v) + ' km/h', 'right', corVelocidade(v), '700')
    + '</tr>';
}

const tabela = (cabecalhos, linhas) =>
  '<tr><td style="padding:0 32px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
  + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + '">'
  + '<tr>' + cabecalhos + '</tr>' + linhas + '</table></td></tr>';

// --- Documento ------------------------------------------------------------
const html = '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
+ '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
+ '<link href="https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;600;700&display=swap" rel="stylesheet">'
+ '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + FONTE + '">'

+ '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
+ '<tr><td align="center">'
+ '<table width="700" cellpadding="0" cellspacing="0" style="max-width:700px;width:100%;'
+ 'background:' + BRANCO + ';border:1.6px solid ' + BORDA + ';border-radius:12px">'

// Cabecalho: marca a esquerda, contexto ao lado, referencia a direita.
// Fechado pela divisoria de 3 px em vinho (secao 3.5).
+ '<tr><td style="padding:24px 32px 18px;border-bottom:3px solid ' + VINHO + '">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle" width="140" style="padding-right:22px">'
+ '<img src="' + LOGO_ESCURA + '" width="128" style="display:block;width:128px;height:auto" alt="Grupo Gritsch">'
+ '</td>'
+ '<td valign="middle">'
+ '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Torre de Controle</div>'
+ '<div style="font-size:23px;font-weight:600;color:' + AZUL + ';margin-top:4px">Relatório de Velocidade</div>'
+ '<div style="font-size:13px;color:' + CINZA + ';margin-top:3px">' + (d.filial || '—') + '</div>'
+ '</td>'
+ '<td valign="middle" align="right">'
+ '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Referência</div>'
+ '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">' + (d.dataRef || '—') + '</div>'
+ '</td>'
+ '</tr></table></td></tr>'

// Fileira de KPI (7.4). Velocidade maxima ganha cor so quando e desvio.
+ '<tr><td style="padding:24px 24px 4px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ boxKpi('Eventos', fmtNum(d.totalEventos), '', AZUL)
+ boxKpi('Velocidade máxima', fmtDec(d.velMax), 'km/h', (d.velMax >= 120 ? ALERTA : AZUL))
+ boxKpi('Velocidade média', fmtDec(d.velMedia), 'km/h', AZUL)
+ '</tr></table></td></tr>'

+ boxResumo

+ faixaSecao('Top 10 ocorrências mais graves')
+ tabela(th('Placa') + th('Modelo') + th('Origem', 'center')
       + th('Velocidade', 'right') + th('Data/hora') + th('Local'), rowsTop)

+ faixaSecao('Alertas por placa (Top 15)')
+ tabela(th('Placa') + th('Modelo') + th('Origem', 'center')
       + th('Qtd', 'center') + th('Pico', 'right'), rowsPlacas)

// Rodape institucional, logo branca sobre azul da marca
+ '<tr><td style="padding:24px 32px;background:' + AZUL + ';border-radius:0 0 10px 10px">'
+ '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
+ '<td valign="middle">'
+ '<img src="' + LOGO_BRANCA + '" width="110" style="display:block;width:110px;height:auto" alt="Gritsch">'
+ '</td>'
+ '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7">'
+ 'Relatório automático da Torre de Controle<br>'
+ 'Fontes: 3STEC, Nuxeo e Omnilink<br>'
+ 'torredecontrole@gritsch.com.br'
+ '</td>'
+ '</tr></table></td></tr>'

+ '</table></td></tr></table></body></html>';

return [{ json: { ...d, htmlEmail: html } }];

// Consolida dados de TODAS as filiais para o email geral pro Gabriel
// Pega os dados do node 14 (que agrupou por filial antes do loop)
const filiais = $('14 - Agrupar por Filial + KPIs').all();
const dataRef = $('02 - Calcular Periodo').first().json.dataRef;

// Se não teve eventos no dia
if (filiais.length === 0 || (filiais.length === 1 && filiais[0].json._semEventos)) {
  return [{ json: {
    _semEventos: true,
    dataRef: dataRef,
    totalFiliais: 0,
    totalEventosGeral: 0,
    velMaxGeral: 0,
    velMediaGeral: 0,
    rankingFiliais: [],
    piorOfensorGeral: null,
    consolidadoDestinatarios: filiais[0]?.json?.consolidadoDestinatarios || 'jefferson@gritsch.com.br',
    consolidadoCC: filiais[0]?.json?.consolidadoCC || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br'
  }}];
}

// Totais gerais
let totalEventosGeral = 0;
let velMaxGeral = 0;
let somaVelMedia = 0;
let countVelMedia = 0;

// Ranking de filiais (ordenado por qtd de eventos)
const rankingFiliais = [];
// Pior ofensor global (placa com mais alertas considerando todas as filiais)
let piorOfensorGeral = null;

for (const item of filiais) {
  const f = item.json;
  if (f._semEventos) continue;

  totalEventosGeral += (f.totalEventos || 0);
  if ((f.velMax || 0) > velMaxGeral) velMaxGeral = f.velMax;
  if (f.velMedia > 0) {
    somaVelMedia += f.velMedia * f.totalEventos;
    countVelMedia += f.totalEventos;
  }

  // Top placa da filial (primeira da tabelaPlacas, que ja vem ordenada por qtd)
  const topPlaca = (f.tabelaPlacas && f.tabelaPlacas[0]) || null;

  rankingFiliais.push({
    filial: f.filial,
    totalEventos: f.totalEventos || 0,
    velMax: f.velMax || 0,
    velMedia: f.velMedia || 0,
    qtdPlacasEnvolvidas: (f.tabelaPlacas || []).length,
    topPlaca: topPlaca ? {
      placa: topPlaca.placa,
      modelo: topPlaca.modelo || '',
      qtd: topPlaca.qtd,
      velMax: topPlaca.velMax
    } : null
  });

  // Candidato a pior ofensor global
  if (topPlaca) {
    if (!piorOfensorGeral || topPlaca.qtd > piorOfensorGeral.qtd) {
      piorOfensorGeral = {
        placa: topPlaca.placa,
        modelo: topPlaca.modelo || '',
        qtd: topPlaca.qtd,
        velMax: topPlaca.velMax,
        filial: f.filial
      };
    }
  }
}

rankingFiliais.sort((a, b) => b.totalEventos - a.totalEventos);

const velMediaGeral = countVelMedia > 0 ? Math.round((somaVelMedia / countVelMedia) * 100) / 100 : 0;

return [{ json: {
  dataRef: dataRef,
  totalFiliais: rankingFiliais.length,
  totalEventosGeral: totalEventosGeral,
  velMaxGeral: velMaxGeral,
  velMediaGeral: velMediaGeral,
  rankingFiliais: rankingFiliais,
  piorOfensorGeral: piorOfensorGeral,
  consolidadoDestinatarios: filiais[0]?.json?.consolidadoDestinatarios || 'jefferson@gritsch.com.br',
  consolidadoCC: filiais[0]?.json?.consolidadoCC || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br',
  _semEventos: false
}}];

// ===========================================================================
// Gerar HTML Geral  (identidade visual Grupo Gritsch, v1.0)
//
// Consolidado de todas as filiais, para a diretoria. Mesma estrutura aprovada,
// mesma paleta e mesmos componentes de "18 - Gerar HTML Email".
// Ver aquele arquivo para o mapeamento completo secao-a-secao do design system.
// ===========================================================================

const d = $json;

const fmtNum = (n) => String(n ?? 0).replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmtDec = (n) => String(n ?? 0).replace('.', ',');

const AZUL = '#213035', VINHO = '#8E2E2F', ALERTA = '#FA1126', CRITICO = '#5A181C';
const ATENCAO = '#E8A33D', POSITIVO = '#13880D', CINZA = '#4E4D4D';
const BORDA = '#BFBFBF', REGUA = '#E2E2E2', FUNDO = '#F2F2F2', BRANCO = '#FFFFFF';

const FONTE = "'Roboto Condensed','Arial Narrow',Arial,sans-serif";

// Colorida no cabecalho branco, branca no rodape azul. Ambas a ESQUERDA.
const LOGO_ESCURA = 'https://gritsch.com.br/wp-content/uploads/2022/03/logomarca-1_gritsch-1.png';
const LOGO_BRANCA = 'https://gritsch.com.br/wp-content/uploads/2023/07/logo_branca1080.png';

const corVelocidade = (v) => (v >= 140 ? CRITICO : v >= 120 ? ALERTA : ATENCAO);

// Destinatários do consolidado centralizados no Banco de Dados (torre.email_gritsch_config)
const emailDestinoConsolidado = d.consolidadoDestinatarios || 'jefferson@gritsch.com.br';
const emailCCConsolidado = d.consolidadoCC || 'sandro@gritsch.com.br,torredecontrole@gritsch.com.br,flavio@gritsch.com.br,fabio.pepplow@gritsch.com.br';

const abre = () =>
  '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8">'
  + '<meta name="viewport" content="width=device-width,initial-scale=1.0">'
  + '<link href="https://fonts.googleapis.com/css2?family=Roboto+Condensed:wght@400;600;700&display=swap" rel="stylesheet">'
  + '</head><body style="margin:0;padding:0;background:' + FUNDO + ';font-family:' + FONTE + '">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';padding:28px 0">'
  + '<tr><td align="center">'
  + '<table width="760" cellpadding="0" cellspacing="0" style="max-width:760px;width:100%;'
  + 'background:' + BRANCO + ';border:1.6px solid ' + BORDA + ';border-radius:12px">';

// Rodape institucional: logo branca sobre o azul da marca
const rodape = () =>
  '<tr><td style="padding:24px 32px;background:' + AZUL + ';border-radius:0 0 10px 10px">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td valign="middle">'
  + '<img src="' + LOGO_BRANCA + '" width="120" style="display:block;width:120px;height:auto" alt="Gritsch">'
  + '</td>'
  + '<td valign="middle" align="right" style="font-size:11px;color:' + BRANCO + ';line-height:1.7">'
  + 'Relatório automático da Torre de Controle<br>'
  + 'Fontes: 3STEC, Nuxeo e Omnilink<br>'
  + 'torredecontrole@gritsch.com.br'
  + '</td></tr></table></td></tr>'
  + '</table></td></tr></table></body></html>';

const cabecalho = (subtitulo) =>
  '<tr><td style="padding:24px 32px 18px;border-bottom:3px solid ' + VINHO + '">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td valign="middle" width="140" style="padding-right:22px">'
  + '<img src="' + LOGO_ESCURA + '" width="128" style="display:block;width:128px;height:auto" alt="Grupo Gritsch">'
  + '</td>'
  + '<td valign="middle">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Torre de Controle</div>'
  + '<div style="font-size:23px;font-weight:600;color:' + AZUL + ';margin-top:4px">Visão Geral Diária</div>'
  + '<div style="font-size:13px;color:' + CINZA + ';margin-top:3px">' + subtitulo + '</div>'
  + '</td>'
  + '<td valign="middle" align="right">'
  + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">Referência</div>'
  + '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">' + (d.dataRef || '—') + '</div>'
  + '</td></tr></table></td></tr>';

// ---------------------------------------------------------------------------
// Dia sem evento. Unico lugar do relatorio onde o verde e correto: e um
// resultado dentro da meta, e nao e box de KPI (regra 5.3 do design system).
// ---------------------------------------------------------------------------
if (d._semEventos) {
  const vazio = abre()
    + cabecalho('Consolidado de todas as filiais')
    + '<tr><td style="padding:44px 32px;text-align:center">'
    + '<table cellpadding="0" cellspacing="0" align="center" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + POSITIVO + ';border-radius:0 8px 8px 0">'
    + '<tr><td style="padding:18px 28px;text-align:left">'
    + '<div style="font-size:12px;font-weight:700;text-transform:uppercase;color:' + POSITIVO + '">Dentro da meta</div>'
    + '<div style="font-size:20px;font-weight:600;color:' + AZUL + ';margin-top:6px">Nenhum evento de velocidade no período</div>'
    + '<div style="font-size:13px;color:' + CINZA + ';margin-top:6px">Toda a frota monitorada operou dentro do limite da sua classe.</div>'
    + '</td></tr></table></td></tr>'
    + rodape();
  return [{ json: { ...d, htmlEmail: vazio, emailDestino: emailDestinoConsolidado, emailCC: emailCCConsolidado } }];
}

// --- KPI ------------------------------------------------------------------
const boxKpi = (rotulo, valor, unidade, corNumero) =>
  '<td width="25%" valign="top" style="padding:0 6px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + BRANCO + ';'
  + 'border:1.6px solid ' + BORDA + ';border-radius:12px"><tr><td style="padding:14px 18px">'
  + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + ';'
  + 'font-family:' + FONTE + '">' + rotulo + '</div>'
  + '<div style="font-size:26px;font-weight:700;color:' + (corNumero || AZUL) + ';margin-top:4px;'
  + 'font-family:' + FONTE + '">' + valor
  + (unidade ? '<span style="font-size:12px;font-weight:400;color:' + CINZA + '"> ' + unidade + '</span>' : '')
  + '</div></td></tr></table></td>';

// --- Pior ofensor ---------------------------------------------------------
let boxPior = '';
if (d.piorOfensorGeral) {
  const p = d.piorOfensorGeral;
  const cor = corVelocidade(p.velMax);
  const nivel = p.velMax >= 140 ? 'Crítico' : p.velMax >= 120 ? 'Alto' : 'Moderado';
  boxPior = '<tr><td style="padding:22px 32px 0">'
    + '<table width="100%" cellpadding="0" cellspacing="0" style="background:' + FUNDO + ';'
    + 'border-left:4px solid ' + cor + ';border-radius:0 8px 8px 0"><tr><td style="padding:16px 22px">'
    + '<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:' + CINZA + '">'
    + 'Veículo com mais alertas · nível ' + nivel + '</div>'
    + '<div style="font-size:15px;color:' + CINZA + ';margin-top:8px;line-height:1.7">'
    + '<span style="font-weight:700;color:' + AZUL + ';font-size:17px">' + p.placa + '</span>'
    + ' · ' + (p.modelo || '—') + ' · ' + (p.filial || '—') + '<br>'
    + '<span style="font-weight:700;color:' + AZUL + '">' + fmtNum(p.qtd) + '</span> alertas no período'
    + ' · pico de <span style="font-weight:700;color:' + cor + '">' + fmtDec(p.velMax) + ' km/h</span>'
    + '</div></td></tr></table></td></tr>';
}

// --- Ranking --------------------------------------------------------------
const th = (txt, align) =>
  '<th style="padding:10px 12px;text-align:' + (align || 'left') + ';font-size:12px;font-weight:700;'
  + 'text-transform:uppercase;color:' + BRANCO + ';background:' + VINHO + ';font-family:' + FONTE + '">' + txt + '</th>';

const td = (c, align, cor, peso) =>
  '<td style="padding:10px 12px;border-bottom:1.6px solid ' + REGUA + ';font-size:13px;'
  + 'text-align:' + (align || 'left') + ';color:' + (cor || CINZA) + ';font-weight:' + (peso || '400') + ';'
  + 'font-family:' + FONTE + '">' + c + '</td>';

let rowsFiliais = '', pos = 1;
for (const f of (d.rankingFiliais || [])) {
  const topInfo = f.topPlaca ? f.topPlaca.placa + ' (' + f.topPlaca.qtd + 'x)' : '—';
  rowsFiliais += '<tr>'
    + td(pos, 'center', BORDA, '700')
    + td(f.filial, 'left', AZUL, '700')
    + td(fmtNum(f.totalEventos), 'center')
    + td(f.qtdPlacasEnvolvidas, 'center')
    + td(fmtDec(f.velMax) + ' km/h', 'right', corVelocidade(f.velMax), '700')
    + td(topInfo, 'left')
    + '</tr>';
  pos++;
}

const faixaSecao = (titulo) =>
  '<tr><td style="padding:26px 32px 0"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + '<td style="background:' + VINHO + ';border-radius:10px 10px 0 0;padding:9px 20px;'
  + 'font-size:14px;font-weight:700;color:' + BRANCO + ';font-family:' + FONTE + '">' + titulo + '</td>'
  + '</tr></table></td></tr>';

const html = abre()
  + cabecalho('Consolidado de todas as filiais')
  + '<tr><td style="padding:24px 26px 4px"><table width="100%" cellpadding="0" cellspacing="0"><tr>'
  + boxKpi('Eventos totais', fmtNum(d.totalEventosGeral), '', AZUL)
  + boxKpi('Filiais', fmtNum(d.totalFiliais), '', AZUL)
  + boxKpi('Velocidade máxima', fmtDec(d.velMaxGeral), 'km/h', (d.velMaxGeral >= 120 ? ALERTA : AZUL))
  + boxKpi('Velocidade média', fmtDec(d.velMediaGeral), 'km/h', AZUL)
  + '</tr></table></td></tr>'
  + boxPior
  + faixaSecao('Ranking entre filiais')
  + '<tr><td style="padding:0 32px">'
  + '<table width="100%" cellpadding="0" cellspacing="0" style="border:1.6px solid ' + BORDA + ';'
  + 'border-top:none;border-radius:0 0 12px 12px;background:' + BRANCO + '">'
  + '<tr>' + th('#', 'center') + th('Filial') + th('Eventos', 'center')
  + th('Placas', 'center') + th('Pico', 'right') + th('Top alertas') + '</tr>'
  + rowsFiliais + '</table></td></tr>'
  + rodape();

return [{ json: { ...d, htmlEmail: html, emailDestino: emailDestinoConsolidado, emailCC: emailCCConsolidado } }];
